try {
  if (!localStorage.getItem('cp.lang')) {
    if (Object.keys(localStorage).some((k) => k.startsWith('mps.'))) { localStorage.setItem('mps.langSet', '1'); localStorage.setItem('cp.lang', 'ru'); } else I18n.set('en');
  }
} catch { /* нет хранилища — останется русский */ }
